const resultats = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: { name: "Résultats des trades fermés",  parameters: { mode: 'runOnceForAllItems', language: 'javaScript', jsCode: "// Petits outils communs : lire la réponse d'un nœud du bridge sous forme de liste.\nfunction liste(nom) {\n  let a = [];\n  try { a = $(nom).all().map(function (i) { return i.json; }); } catch (e) { return []; }\n  // le bridge peut renvoyer soit une liste, soit un objet qui contient la liste\n  if (a.length === 1 && a[0] && typeof a[0] === 'object') {\n    const cles = Object.keys(a[0]);\n    const k = cles.find(function (c) { return Array.isArray(a[0][c]); });\n    if (k && cles.length <= 3) a = a[0][k];\n  }\n  return a.filter(function (x) { return x && typeof x === 'object' && !x.error && Object.keys(x).length > 0; });\n}\nfunction nombre(v) { const n = Number(v); return Number.isFinite(n) ? n : NaN; }\n// Résultat net d'un deal de clôture (mêmes champs que le bot principal)\nfunction netDeal(d) {\n  const c = d.closePositionDetail;\n  if (d.netProfit !== undefined && d.netProfit !== null) return nombre(d.netProfit);\n  if (c) return (nombre(c.grossProfit) || 0) + (nombre(c.swap) || 0) + (nombre(c.commission) || 0);\n  if (d.grossProfit !== undefined) return (nombre(d.grossProfit) || 0) + (nombre(d.swap) || 0) + (nombre(d.commission) || 0);\n  if (d.profit !== undefined) return nombre(d.profit);\n  return NaN;\n}\nfunction estCloture(d) { return d.type === 'close' || !!d.closePositionDetail; }\nfunction texteEtiquette(x) { return String(x.label || x.comment || ''); }\n\n// Met à jour le résultat des trades du journal encore « ouverts ».\n//  - ordre limite encore en attente ou position encore ouverte sur l'actif : on attend ;\n//  - deals de clôture du bot sur l'actif depuis l'ordre : gagnant / perdant (en R) ;\n//  - rien de tout ça après l'heure d'expiration : l'ordre n'a pas été déclenché (expiré).\nconst cfg = $('Configuration').first().json;\nfunction estDuBot(x) { const t = texteEtiquette(x) + ' ' + String(x.comment || ''); return t.indexOf(cfg.label) >= 0 || t.indexOf(cfg.commentaire) >= 0; }\nconst lignes = liste('Journal SMC Vision').filter(function (r) { return r.statut === 'execute' && r.resultat === 'ouvert'; });\nconst deals = liste('Deals récents').filter(estCloture);\nconst avecEtiquette = deals.some(function (d) { return texteEtiquette(d) !== '' || d.comment; });\nconst positions = liste('Positions ouvertes'), ordres = liste('Ordres en attente');\nconst sorties = [];\nfor (const l of lignes) {\n  const depuis = Date.parse(l.horodatage);\n  const ids = String(l.ordres || '').split(',').filter(Boolean);\n  const encore = positions.concat(ordres).some(function (p) { return p.symbol === l.symbole && (ids.indexOf(String(p.orderId || '')) >= 0 || ids.indexOf(String(p.positionId || '')) >= 0 || estDuBot(p) || !texteEtiquette(p)); });\n  if (encore) continue;\n  const ds = deals.filter(function (d) {\n    const t = Date.parse(d.time || d.executionTime || d.timestamp || '');\n    return d.symbol === l.symbole && (!Number.isFinite(t) || t >= depuis) && (!avecEtiquette || estDuBot(d));\n  }).slice(0, Math.max(1, ids.length));\n  if (ds.length) {\n    const net = ds.reduce(function (s, d) { return s + (netDeal(d) || 0); }, 0);\n    const r = Number(l.risque_montant) > 0 ? net / Number(l.risque_montant) : null;\n    sorties.push({ json: { id: l.id, resultat: (net >= 0 ? 'gagnant' : 'perdant') + (r !== null ? ' (' + r.toFixed(2) + 'R)' : ''), resultat_montant: Math.round(net * 100) / 100 } });\n  } else if (Date.now() > Date.parse(l.expire_a || '') + 10 * 60000) {\n    sorties.push({ json: { id: l.id, resultat: 'expiré (ordre limite non déclenché)', resultat_montant: 0 } });\n  }\n}\nreturn sorties;\n" } }
});

const majJournal = node({
  type: 'n8n-nodes-base.dataTable',
  version: 1.1,
  config: {
    name: 'Mettre à jour le résultat',
    parameters: {
      resource: 'row', operation: 'update',
      dataTableId: { __rl: true, mode: 'id', value: 'T1SH2vr9hn0f1Ahm' },
      matchType: 'allConditions',
      filters: { conditions: [ { keyName: 'id', condition: 'eq', keyValue: expr('{{ $json.id }}') } ] },
      columns: { mappingMode: 'defineBelow', value: { resultat: expr('{{ $json.resultat }}'), resultat_montant: expr('{{ $json.resultat_montant }}') },
        schema: [ { id: 'resultat', displayName: 'resultat', required: false, defaultMatch: false, display: true, type: 'string', canBeUsedToMatch: true },
                  { id: 'resultat_montant', displayName: 'resultat_montant', required: false, defaultMatch: false, display: true, type: 'number', canBeUsedToMatch: true } ] }
    }
  }
});
const preparer = node({
  type: 'n8n-nodes-base.code',
  version: 2,
  config: { name: "Préparer le cycle",  parameters: { mode: 'runOnceForAllItems', language: 'javaScript', jsCode: "// Petits outils communs : lire la réponse d'un nœud du bridge sous forme de liste.\nfunction liste(nom) {\n  let a = [];\n  try { a = $(nom).all().map(function (i) { return i.json; }); } catch (e) { return []; }\n  // le bridge peut renvoyer soit une liste, soit un objet qui contient la liste\n  if (a.length === 1 && a[0] && typeof a[0] === 'object') {\n    const cles = Object.keys(a[0]);\n    const k = cles.find(function (c) { return Array.isArray(a[0][c]); });\n    if (k && cles.length <= 3) a = a[0][k];\n  }\n  return a.filter(function (x) { return x && typeof x === 'object' && !x.error && Object.keys(x).length > 0; });\n}\nfunction nombre(v) { const n = Number(v); return Number.isFinite(n) ? n : NaN; }\n// Résultat net d'un deal de clôture (mêmes champs que le bot principal)\nfunction netDeal(d) {\n  const c = d.closePositionDetail;\n  if (d.netProfit !== undefined && d.netProfit !== null) return nombre(d.netProfit);\n  if (c) return (nombre(c.grossProfit) || 0) + (nombre(c.swap) || 0) + (nombre(c.commission) || 0);\n  if (d.grossProfit !== undefined) return (nombre(d.grossProfit) || 0) + (nombre(d.swap) || 0) + (nombre(d.commission) || 0);\n  if (d.profit !== undefined) return nombre(d.profit);\n  return NaN;\n}\nfunction estCloture(d) { return d.type === 'close' || !!d.closePositionDetail; }\nfunction texteEtiquette(x) { return String(x.label || x.comment || ''); }\n\n// Prépare le cycle : règles de risque du compte, puis liste des actifs à analyser.\nconst cfg = $('Configuration').first().json;\nconst solde = nombre($('Solde du compte').first().json.balance);\n// Risque dégressif : on prend le premier palier dont la limite est au-dessus du solde.\n// Sécurité : jamais plus de 5 %, et 1 % si le solde est illisible.\nfunction risqueSelonSolde(s) {\n  if (!(s > 0)) return 1;\n  const p = (cfg.paliersRisque || []).find(function (x) { return s < x.jusqu_a; });\n  return Math.min(p ? p.risque : (Number(cfg.risqueAuDela) || 1), 5);\n}\nconst risquePct = risqueSelonSolde(solde);\n// Un ordre / une position / un deal du bot : étiquette ou commentaire SMCV / SMC-Vision.\nfunction estDuBot(x) { const t = texteEtiquette(x) + ' ' + String(x.comment || ''); return t.indexOf(cfg.label) >= 0 || t.indexOf(cfg.commentaire) >= 0; }\n\n// 1) Pertes du jour (jour de Paris), comptées sur les trades du bot.\n//    Si le bridge ne donne pas l'étiquette des deals, on compte toutes les pertes du compte (plus prudent).\nconst deals = liste('Deals du jour').filter(estCloture);\nconst avecEtiquette = deals.some(function (d) { return texteEtiquette(d) !== ''; });\nconst dealsBot = avecEtiquette ? deals.filter(estDuBot) : deals;\nconst seuil = -0.25 * solde * risquePct / 100; // une vraie perte, pas un petit résultat négatif\n// Une perte = un TRADE perdant : les deux demi-ordres d'un même trade, clôturés ensemble\n// (même actif, même tranche de 5 minutes), ne comptent que pour une seule perte.\nconst parTrade = {};\ndealsBot.forEach(function (d, k) {\n  const t = Date.parse(d.time || d.executionTime || d.timestamp || '');\n  const cle = Number.isFinite(t) ? d.symbol + '|' + Math.floor(t / 300000) : 'deal' + k;\n  parTrade[cle] = (parTrade[cle] || 0) + (netDeal(d) || 0);\n});\nconst pertes = Object.keys(parTrade).filter(function (k) { return parTrade[k] < seuil; }).length;\nif (pertes >= cfg.maxPertesJour) return [];\n\n// 2) Ce qui est déjà engagé : positions ouvertes et ordres en attente.\nconst positions = liste('Positions ouvertes');\nconst ordres = liste('Ordres en attente');\nconst engages = positions.concat(ordres).map(function (p) { return p.symbol; });\nconst ordresBot = ordres.filter(estDuBot);\nconst posEtiquette = positions.some(function (p) { return texteEtiquette(p) !== ''; });\nconst posBot = posEtiquette ? positions.filter(estDuBot) : positions;\n// un trade = une position ou un ordre limite (deux demi-ordres comptent pour un trade par actif)\nconst actifsBot = uniquesSymboles(posBot.concat(ordresBot));\nif (actifsBot >= cfg.maxPositionsBot) return [];\nfunction uniquesSymboles(l) { const v = {}; l.forEach(function (x) { v[x.symbol] = 1; }); return Object.keys(v).length; }\n\n// 3) Mémoire : les mouvements déjà tradés (pas de nouveau trade dans un mouvement déjà joué).\nconst il_y_a_30j = Date.now() - 30 * 86400000;\nconst legs = liste('Journal SMC Vision')\n  .filter(function (r) { return r.statut === 'execute' && r.cle_mouvement && !/^expiré/.test(String(r.resultat || '')) && Date.parse(r.horodatage) >= il_y_a_30j; })\n  .map(function (r) { return r.cle_mouvement; });\n\nreturn cfg.actifs\n  .filter(function (a) { return engages.indexOf(a.symbol) < 0; })\n  .map(function (a) { return { json: Object.assign({}, a, { legsDejaTradees: legs, pertesDuJour: pertes, solde: solde, risquePct: risquePct }) }; });\n" } }
});

